32	export interface SessionManager<T extends SessionDataT = SessionDataT> {
33	  readonly id: string | undefined;
34	  readonly data: SessionData<T>;
35	  update: (update: SessionUpdate<T>) => Promise<SessionManager<T>>;
36	  clear: () => Promise<SessionManager<T>>;
37	}
